// Shared column builders so every module's tables follow the same conventions
// (docs/architecture.md "Data conventions", docs/adr/0005 and 0007). Not re-exported from
// ./index.ts because it defines no tables.
import { sql } from 'drizzle-orm';
import { bigint, char, customType, integer, numeric, text, timestamp, uuid } from 'drizzle-orm/pg-core';
const ts = timestamp;

/** UUID primary key generated by Postgres (gen_random_uuid() is built in since PostgreSQL 13). */
export const idColumn = () =>
  uuid('id')
    .primaryKey()
    .default(sql`gen_random_uuid()`);

/**
 * Tenant owner. Every tenant-owned table has it NOT NULL and indexed, and child tables reference
 * parents with a composite FK (org_id, parent_id) -> parent(org_id, id) so a row can never point
 * at another tenant's data. Row-Level Security policies compare it to current_setting('app.org_id').
 */
export const orgIdColumn = () => uuid('org_id').notNull();

/** Optimistic concurrency: PATCH requires If-Match with the current revision (mismatch -> 412). */
export const revisionColumn = () => integer('revision').notNull().default(1);

/** timestamptz, always UTC. */
export const createdAtColumn = () =>
  timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();
export const updatedAtColumn = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();

// ---------------------------------------------------------------- money, rates, PostGIS

/** Integer minor units (cents). bigint in SQL, JS number in TS (safe below 2^53). */
export const minorUnits = (name: string) => bigint(name, { mode: 'number' });
/** ISO 4217 currency code. */
export const currencyColumn = (name = 'currency') => char(name, { length: 3 }).notNull().default('USD');
/** Unit rates and quantities that must never be JS floats: numeric(18,6), read as strings. */
export const rateColumn = (name: string) => numeric(name, { precision: 18, scale: 6 });
/** Soft delete marker, only on tables whose retention policy needs it. */
export const deletedAtColumn = () => ts('deleted_at', { withTimezone: true, mode: 'date' });
export const tsColumn = (name: string) => ts(name, { withTimezone: true, mode: 'date' });
export const textColumn = (name: string) => text(name);

export type GeometryKind =
  | 'Point'
  | 'LineString'
  | 'Polygon'
  | 'MultiPolygon'
  | 'MultiLineString'
  | 'Geometry';

/**
 * PostGIS geometry(kind, 4326). Values travel as text: write EWKT or WKT
 * (e.g. 'SRID=4326;POINT(-97.1 32.7)'); reads return the driver's hex EWKB, so query with
 * ST_AsGeoJSON(...) when you need coordinates back.
 */
export const geometry = (name: string, kind: GeometryKind) =>
  customType<{ data: string; driverData: string }>({
    dataType: () => `geometry(${kind},4326)`,
  })(name);

/** PostGIS geography(kind, 4326) for distance/area on the spheroid (meters). */
export const geography = (name: string, kind: GeometryKind = 'Point') =>
  customType<{ data: string; driverData: string }>({
    dataType: () => `geography(${kind},4326)`,
  })(name);
